def public_lesson(lesson: dict[str, Any], include_answers: bool = False) -> dict[str, Any]:
    result = {key: value for key, value in lesson.items() if key != "practice"}
    practice = []
    for exercise in lesson["practice"]:
        public_exercise = {key: value for key, value in exercise.items() if key != "options"}
        public_exercise["options"] = [
            {key: value for key, value in option.items() if include_answers or key in {"id", "text"}}
            for option in exercise["options"]
        ]
        practice.append(public_exercise)
    result["practice"] = practice
    return result
